def solve():
    for k in range(1, 11):
        k2 = k*k
        target_b_sq = 7 * k2
        for a1 in range(k, -k-1, -1):
            a1_sq = a1*a1
            if a1_sq > k2: continue
            for a2 in range(k, -k-1, -1):
                a2_sq = a2*a2
                if a1_sq + a2_sq > k2: continue
                for a3 in range(k, -k-1, -1):
